const cfg = items[0].json;
const urls = Array.isArray(cfg.searchUrls) ? cfg.searchUrls : [];
return urls.map((url) => ({
  json: {
    ...cfg,
    url
  }
}));

const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

function parsePriceToMonthly(priceText) {
  const t = String(priceText || '');
  const m = t.replace(/,/g, '').match(/€\s?(\d+(?:\.\d+)?)/);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  if (/week/i.test(t)) return Math.round(n * 52 / 12);
  return Math.round(n);
}

function bedsNum(v) {
  const m = String(v || '').match(/(\d+)/);
  return m ? Number(m[1]) : 0;
}

function extractListings(html, sourceUrl) {
  const match = String(html).match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
  if (!match) return [];
  let data;
  try { data = JSON.parse(match[1]); } catch (e) { return []; }
  const list = (((data || {}).props || {}).pageProps || {}).listings || [];
  const out = [];
  for (const row of list) {
    const L = row.listing || row;
    if (!L || !L.id) continue;
    const title = L.title || '';
    const path = L.seoFriendlyPath || '';
    const url = path
      ? `https://www.daft.ie${path}`
      : `https://www.daft.ie/for-rent/${String(title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}/${L.id}`;

    if (/property-for-rent\/tipperary(?:[\/?]|$)/i.test(sourceUrl)) {
      if (!/roscrea/i.test(title) && !/roscrea/i.test(path)) continue;
    }

    const monthly = parsePriceToMonthly(L.price);
    const beds = bedsNum(L.numBedrooms);
    if (Number(cfg.maxMonthlyEuro) > 0 && monthly && monthly > Number(cfg.maxMonthlyEuro)) continue;
    if (Number(cfg.minBeds) > 0 && beds < Number(cfg.minBeds)) continue;

    out.push({
      id: String(L.id),
      title,
      price: L.price || '',
      monthly,
      beds: L.numBedrooms || '',
      baths: L.numBathrooms || '',
      propertyType: L.propertyType || '',
      seller: (L.seller && L.seller.name) || '',
      sellerType: (L.seller && L.seller.sellerType) || '',
      url,
      sourceUrl
    });
  }
  return out;
}

const all = [];
const seenBatch = new Set();
const urlItems = $('Split Search URLs').all();
for (let i = 0; i < items.length; i++) {
  const htmlRaw = items[i].json;
  const html = typeof htmlRaw === 'string'
    ? htmlRaw
    : (htmlRaw.data || htmlRaw.body || htmlRaw.html || '');
  const sourceUrl = (urlItems[i] && urlItems[i].json.url) || '';
  for (const L of extractListings(html, sourceUrl)) {
    if (seenBatch.has(L.id)) continue;
    seenBatch.add(L.id);
    all.push(L);
  }
}

const fresh = [];
const now = Date.now();
for (const L of all) {
  if (staticData.seen[L.id]) continue;
  staticData.seen[L.id] = now;

  const text = [
    `🚨 ROSCREA RENTAL — ACT NOW`,
    ``,
    `📍 ${L.title}`,
    `💶 ${L.price}${L.monthly ? ` (~€${L.monthly}/mo)` : ''} · ${L.beds || '?'} · ${L.propertyType || ''}`.trim(),
    `👤 ${L.seller || 'Seller'}${L.sellerType ? ` (${L.sellerType})` : ''}`,
    ``,
    `🔗 ${L.url}`,
    ``,
    `Action:`,
    `1) Open link now`,
    `2) Call if phone is visible`,
    `3) Else send Daft enquiry immediately`,
    ``,
    `Script:`,
    `Hi, I'm interested in the Roscrea rental on Daft.`,
    `Is it still available for viewing this week?`
  ].join('\n');

  fresh.push({
    json: {
      ...L,
      telegramChatId: cfg.telegramChatId,
      sheetId: cfg.sheetId,
      text,
      status: 'new',
      foundAt: new Date(now).toISOString()
    }
  });
}

const entries = Object.entries(staticData.seen).sort((a,b) => b[1]-a[1]);
if (entries.length > 500) {
  staticData.seen = Object.fromEntries(entries.slice(0, 500));
}

return fresh;

const cfg = $('Config').first().json;
const sheetId = String(cfg.sheetId || '').trim();
if (!sheetId) return [];
return items.map(i => ({ json: { ...i.json, sheetId } }));
